/**
 * Which "commander units" ΓÇö solo cards, or legal pairs ΓÇö can be built from a
 * pool of eligible candidates under the Partner-family of abilities.
 */

export type PartnerAbility =
  | 'partner'
  | 'partner_with'
  | 'partner_suffix'
  | 'friends_forever'
  | 'choose_background'
  | 'doctors_companion'
  | null;

/**
 * The slice of a card these rules need. `creature_types` matches Scryfall
 * bulk data's own JSON-encoded-string column shape (the common storage
 * form for it) rather than a parsed array ΓÇö keeping this the same shape a
 * caller's own card type already has (e.g. commander-recommender's
 * `CardRow`) means `buildCommanderUnits` can return the caller's exact
 * card objects unmodified, not a reshaped copy that would then mismatch
 * every other place those same objects flow through.
 */
export interface PartnerCardLike {
  oracle_id: string;
  name_lower: string;
  type_line?: string | null;
  creature_types: string;
  partner_ability: PartnerAbility;
  partner_target: string | null;
}

/** Decodes creature_types' JSON-string-array shape, tolerating a malformed value. */
function parseCreatureTypes(json: string): string[] {
  try {
    const parsed = JSON.parse(json);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/**
 * A commander as actually played: one card, or two under a Partner-family
 * ability (702.124). Every card in `cards` is jointly "the commander" ΓÇö
 * there's no primary/secondary in the rules (702.124e), so this is an array
 * rather than a "main card + optional partner" shape.
 */
export interface CommanderUnit<TCard extends PartnerCardLike = PartnerCardLike> {
  cards: TCard[];
}

function creatureTypeSet(card: PartnerCardLike): Set<string> {
  return new Set(parseCreatureTypes(card.creature_types));
}

function setEquals(a: Set<string>, b: Set<string>): boolean {
  return a.size === b.size && [...a].every((item) => b.has(item));
}

/** Stable id for a unit, used to dedupe pairs regardless of which card was found first. */
export function unitKey(unit: CommanderUnit): string {
  return unit.cards
    .map((c) => c.oracle_id)
    .sort()
    .join('+');
}

/**
 * Builds every legal "commander unit" from the eligible candidate pool: one
 * per solo card, plus one per valid Partner/Partner-with/PartnerΓÇösuffix/
 * Friends-forever/Choose-a-Background/Doctor's-companion pair.
 *
 * Pairing is grouped by ability variant rather than a blind cross-product
 * over every candidate ΓÇö with an eligible pool in the tens to low hundreds,
 * pairing only within (or against) the relevant sub-groups keeps this cheap
 * enough to run per request, which is what was asked for. Different partner
 * variants never combine with each other (702.124f) ΓÇö a plain-Partner card
 * cannot pair with a Partner-with card, for instance ΓÇö which pairing only
 * within each group already guarantees.
 *
 * A card with a partner ability still gets its own solo unit too: every
 * variant here is optional (903.3 / 702.124a), so a Partner card is a
 * perfectly legal commander by itself. The one exception is Background
 * enchantments, which never appear as a solo candidate in the first place
 * (they're not a creature/Vehicle/Spacecraft, so a caller's own candidate
 * pool already excludes them) and are only ever reached here as a pairing
 * target.
 */
export function buildCommanderUnits<TCard extends PartnerCardLike>(
  candidates: TCard[],
  backgrounds: TCard[],
): CommanderUnit<TCard>[] {
  const units: CommanderUnit<TCard>[] = candidates.map((card) => ({ cards: [card] }));
  const seenPairs = new Set<string>();

  function addPair(a: TCard, b: TCard): void {
    if (a.oracle_id === b.oracle_id) return;
    const key = [a.oracle_id, b.oracle_id].sort().join('+');
    if (seenPairs.has(key)) return;
    seenPairs.add(key);
    units.push({ cards: [a, b] });
  }

  function pairAllWithin(group: TCard[]): void {
    for (let i = 0; i < group.length; i++) {
      // Both i and j are always within [0, group.length) by the loop bounds.
      for (let j = i + 1; j < group.length; j++) addPair(group[i]!, group[j]!);
    }
  }

  const byAbility = (ability: PartnerAbility) =>
    candidates.filter((c) => c.partner_ability === ability);

  // Plain Partner: any two.
  pairAllWithin(byAbility('partner'));

  // PartnerΓÇö[text]: only within the same suffix group.
  const suffixGroups = new Map<string, TCard[]>();
  for (const card of byAbility('partner_suffix')) {
    const key = card.partner_target ?? '';
    const group = suffixGroups.get(key);
    if (group) group.push(card);
    else suffixGroups.set(key, [card]);
  }
  for (const group of suffixGroups.values()) pairAllWithin(group);

  // Partner with [Name]: symmetric named pairing ΓÇö each card must name the
  // other (702.124j), not just be named by it.
  const byNameLower = new Map(candidates.map((c) => [c.name_lower, c]));
  for (const card of byAbility('partner_with')) {
